"use client";

import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { STATUS_SURFACE, STATUS_TEXT } from "../lib/status";
import { BlockFrame } from "../parts/block-frame";
import { LockIcon, ShieldIcon } from "./icons";
import { type Method, PASSWORD_CHANGED, type Session, SESSIONS } from "./security-settings/data";
import { PasswordForm } from "./security-settings/password-form";
import { SessionList } from "./security-settings/session-list";
import { TwoFactorSetup } from "./security-settings/two-factor-setup";
import { ExpandRegion } from "./shared/expand-region";

const METHOD_NAME = { app: "authenticator app", text: "text message" } satisfies Record<Method, string>;

/**
 * The security page of one account: two-factor sign-in with a guided setup,
 * the password with its last change, and every signed-in device. Revoking a
 * device can be undone for a few seconds.
 */
export function SecuritySettings({ className }: { className?: string }) {
  const [twoFactor, setTwoFactor] = useState<Method | null>(null);
  const [setupOpen, setSetupOpen] = useState(false);
  const [passwordOpen, setPasswordOpen] = useState(false);
  const [passwordDate, setPasswordDate] = useState(PASSWORD_CHANGED);
  const [sessions, setSessions] = useState<Session[]>(SESSIONS);
  const [revoked, setRevoked] = useState<{ session: Session; index: number } | null>(null);
  const [announce, setAnnounce] = useState("");
  const undoTimer = useRef<number | null>(null);
  const titleId = useId();
  const setupId = useId();
  const passwordId = useId();

  useEffect(() => () => {
    if (undoTimer.current) window.clearTimeout(undoTimer.current);
  }, []);

  const others = sessions.filter((session) => !session.current);

  const revoke = (id: string) => {
    const index = sessions.findIndex((session) => session.id === id);
    const session = sessions[index];
    if (!session) return;
    setSessions((current) => current.filter((item) => item.id !== id));
    setRevoked({ session, index });
    setAnnounce(`Signed out ${session.device}.`);
    if (undoTimer.current) window.clearTimeout(undoTimer.current);
    undoTimer.current = window.setTimeout(() => setRevoked(null), 6000);
  };

  const undo = () => {
    if (!revoked) return;
    setSessions((current) => [...current.slice(0, revoked.index), revoked.session, ...current.slice(revoked.index)]);
    setAnnounce(`${revoked.session.device} is signed in again.`);
    setRevoked(null);
  };

  const revokeOthers = () => {
    setSessions((current) => current.filter((session) => session.current));
    setRevoked(null);
    setAnnounce(`Signed out ${others.length} other devices.`);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="border-b border-border px-5 py-4">
        <h2 id={titleId} className="text-base font-semibold">
          Security for Amara Osei
        </h2>
        <p className="text-sm text-muted-foreground">amara@harbourstreet.clinic</p>
      </header>

      <div className="flex flex-col">
        <section aria-labelledby={`${setupId}-title`} className="flex flex-col gap-4 p-5">
          <div className="flex flex-wrap items-center gap-4">
            <span aria-hidden="true" className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-muted">
              <ShieldIcon className="size-5" />
            </span>
            <div className="flex min-w-0 flex-1 flex-col gap-0.5">
              <h3 id={`${setupId}-title`} className="flex flex-wrap items-center gap-2 text-sm font-semibold">
                Two-factor sign-in
                <span
                  className={cn(
                    "rounded-full px-2 py-0.5 text-xs font-medium",
                    twoFactor ? cn(STATUS_SURFACE.good, STATUS_TEXT.good) : cn(STATUS_SURFACE.watch, STATUS_TEXT.watch),
                  )}
                >
                  {twoFactor ? "On" : "Off"}
                </span>
              </h3>
              <p className="text-sm text-muted-foreground">
                {twoFactor ? `Codes come from your ${METHOD_NAME[twoFactor]}.` : "Ask for a code as well as your password when you sign in."}
              </p>
            </div>
            {twoFactor ? (
              <Button variant="outline" onClick={() => setTwoFactor(null)}>
                Turn off
              </Button>
            ) : (
              <Button onClick={() => setSetupOpen((open) => !open)} aria-expanded={setupOpen} aria-controls={setupId}>
                {setupOpen ? "Close setup" : "Enable"}
              </Button>
            )}
          </div>
          <ExpandRegion open={setupOpen && !twoFactor} id={setupId}>
            <TwoFactorSetup
              onCancel={() => setSetupOpen(false)}
              onDone={(method) => {
                setTwoFactor(method);
                setSetupOpen(false);
                setAnnounce("Two-factor sign-in is on.");
              }}
            />
          </ExpandRegion>
        </section>

        <section aria-labelledby={`${passwordId}-title`} className="flex flex-col gap-4 p-5">
          <div className="flex flex-wrap items-center gap-4">
            <span aria-hidden="true" className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-muted">
              <LockIcon className="size-5" />
            </span>
            <div className="flex min-w-0 flex-1 flex-col gap-0.5">
              <h3 id={`${passwordId}-title`} className="text-sm font-semibold">
                Password
              </h3>
              <p className="text-sm text-muted-foreground">Last changed {passwordDate}</p>
            </div>
            <Button variant="outline" onClick={() => setPasswordOpen((open) => !open)} aria-expanded={passwordOpen} aria-controls={passwordId}>
              {passwordOpen ? "Cancel" : "Change"}
            </Button>
          </div>
          <ExpandRegion open={passwordOpen} id={passwordId}>
            <PasswordForm
              onCancel={() => setPasswordOpen(false)}
              onSaved={() => {
                setPasswordDate("today");
                setPasswordOpen(false);
                setAnnounce("Password changed.");
              }}
            />
          </ExpandRegion>
        </section>

        <section aria-labelledby={`${titleId}-sessions`} className="flex flex-col gap-2 p-5">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div>
              <h3 id={`${titleId}-sessions`} className="text-sm font-semibold">
                Signed-in devices
              </h3>
              <p className="text-sm text-muted-foreground">Sign out any device you do not recognise.</p>
            </div>
            <Button variant="ghost" size="sm" onClick={revokeOthers} disabled={others.length === 0}>
              Sign out all others
            </Button>
          </div>
          <SessionList sessions={sessions} onRevoke={revoke} />
          <div className="flex min-h-9 items-center justify-between gap-3 text-sm">
            <p role="status" className="text-muted-foreground">
              {announce}
            </p>
            {revoked ? (
              <Button variant="outline" size="sm" onClick={undo}>
                Undo
              </Button>
            ) : null}
          </div>
        </section>
      </div>
    </BlockFrame>
  );
}

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

