/** The kind of device a session runs on, which picks its icon. */
export type DeviceKind = "laptop" | "phone" | "tablet";

/** One signed-in session. */
export interface Session {
  id: string;
  device: string;
  kind: DeviceKind;
  client: string;
  place: string;
  seen: string;
  /** The session this page is open in. It cannot be revoked here. */
  current?: boolean;
  /** Signed in from a place this account has not used before. */
  newPlace?: boolean;
}

/** The sessions open when the page loads. */
