/** Single-use codes for when the phone is not at hand. */
export const BACKUP_CODES = ["7Q4M-2KXD", "H8ZP-6NRT", "3WCF-9LBA", "KD2V-5YEG", "P6TJ-8QMU", "R9XA-4HNS", "M2LE-7CWK", "Y5BG-3TFP"];

/** The date the password last changed. */
export const PASSWORD_CHANGED = "Jul 14, 2026";

/** A score from 0 to 4 for a new password, with the word for it. */
export function passwordStrength(value: string) {
  let score = 0;
  if (value.length >= 10) score += 1;
  if (value.length >= 14) score += 1;
  if (/[A-Z]/.test(value) && /[a-z]/.test(value)) score += 1;
  if (/\d/.test(value) && /[^A-Za-z0-9]/.test(value)) score += 1;
  const words = ["Too short", "Weak", "Fair", "Good", "Strong"];
  return { score, word: value.length === 0 ? "" : value.length < 10 ? words[0]! : words[score]! };
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { STATUS_TEXT } from "../../lib/status";
import { LoaderIcon } from "../icons";
import { passwordStrength } from "./data";

/** Props for the change-password form. */
export interface PasswordFormProps {
  onSaved: () => void;
  onCancel: () => void;
}

const BAR_TONES = ["bg-chart-5", "bg-chart-4", "bg-chart-3", "bg-chart-2"];

/**
 * The current password, a new one with a four-part strength meter, and Save.
 * The new password needs ten characters; the form says so before it saves.
 */
export function PasswordForm({ onSaved, onCancel }: PasswordFormProps) {
  const [current, setCurrent] = useState("");
  const [next, setNext] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const timer = useRef<number | null>(null);
  const id = useId();
  const strength = passwordStrength(next);

  useEffect(() => () => {
    if (timer.current) window.clearTimeout(timer.current);
  }, []);

  const save = () => {
    if (!current) return setError("Enter your current password.");
    if (next.length < 10) return setError("The new password needs at least 10 characters.");
    setError("");
    setSaving(true);
    timer.current = window.setTimeout(onSaved, 800);
  };

  return (
    <form
      className="grid gap-4 rounded-xl border border-border p-4 @lg:grid-cols-2"
      onSubmit={(event) => {
        event.preventDefault();
        save();
      }}
    >
      <div className="flex flex-col gap-1.5">
        <label htmlFor={`${id}-current`} className="text-sm font-medium">
          Current password
        </label>
        <Input id={`${id}-current`} type="password" autoComplete="current-password" value={current} onChange={(event) => setCurrent(event.target.value)} />
      </div>
      <div className="flex flex-col gap-1.5">
        <label htmlFor={`${id}-next`} className="text-sm font-medium">
          New password
        </label>
        <Input
          id={`${id}-next`}
          type="password"
          autoComplete="new-password"
          value={next}
          aria-describedby={`${id}-strength`}
          onChange={(event) => setNext(event.target.value)}
        />
        <div aria-hidden="true" className="flex gap-1">
          {BAR_TONES.map((tone, index) => (
            <span key={tone} className={cn("h-1 flex-1 rounded-full motion-safe:transition-colors", index < strength.score ? tone : "bg-muted")} />
          ))}
        </div>
        <p id={`${id}-strength`} aria-live="polite" className="min-h-4 text-xs text-muted-foreground">
          {strength.word ? `Strength: ${strength.word}` : "Use 10 or more characters."}
        </p>
      </div>
      <p role="alert" className={cn("min-h-4 text-xs @lg:col-span-2", STATUS_TEXT.bad)}>
        {error}
      </p>
      <div className="flex justify-end gap-2 @lg:col-span-2">
        <Button type="button" variant="ghost" onClick={onCancel}>
          Cancel
        </Button>
        <Button type="submit" disabled={saving}>
          {saving ? <LoaderIcon aria-hidden="true" className="size-4 motion-safe:animate-spin" /> : null}
          Save password
        </Button>
      </div>
    </form>
  );
}

