"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";

import { STATUS_TEXT } from "../../lib/status";
import { KeyIcon, LoaderIcon, TextIcon } from "../icons";
import { BACKUP_CODES, type Method, PHONE, SETUP_KEY, SETUP_STEPS } from "./data";
import { SetupCode } from "./setup-code";
import { StepRail } from "../shared/step-rail";

/** Props for the guided two-factor setup. */
export interface TwoFactorSetupProps {
  onDone: (method: Method) => void;
  onCancel: () => void;
}

const METHODS = [
  { id: "app", label: "Authenticator app", helper: "A code from an app on your phone. Works offline.", Icon: KeyIcon },
  { id: "text", label: "Text message", helper: `A code sent to ${PHONE}.`, Icon: TextIcon },
] as const;

/**
 * Three guided steps: choose how codes arrive, confirm one code, then keep
 * the backup codes. The rail marks the current step, and each step slides in
 * from the side it comes from.
 */
export function TwoFactorSetup({ onDone, onCancel }: TwoFactorSetupProps) {
  const [step, setStep] = useState(0);
  const [direction, setDirection] = useState(1);
  const [method, setMethod] = useState<Method>("app");
  const [code, setCode] = useState("");
  const [checking, setChecking] = useState(false);
  const [error, setError] = useState("");
  const [copied, setCopied] = useState(false);
  const timer = useRef<number | null>(null);
  const railId = useId();
  const codeId = useId();
  const methodLabelId = useId();
  const reduceMotion = useReducedMotion();

  useEffect(() => () => {
    if (timer.current) window.clearTimeout(timer.current);
  }, []);

  const go = (next: number) => {
    setDirection(next > step ? 1 : -1);
    setStep(next);
  };

  const verify = () => {
    if (!/^\d{6}$/.test(code)) {
      setError("Enter the 6 digits the code shows.");
      return;
    }
    setError("");
    setChecking(true);
    timer.current = window.setTimeout(() => {
      setChecking(false);
      if (code === "000000") setError("That code has expired. Try the next one.");
      else go(2);
    }, 700);
  };

  const copy = () => {
    void navigator.clipboard?.writeText(BACKUP_CODES.join("\n")).catch(() => undefined);
    setCopied(true);
  };

  const offset = reduceMotion ? 0 : 24 * direction;

  return (
    <div className="grid gap-4 rounded-xl border border-border p-4 @xl:grid-cols-[12rem_1fr]">
      <StepRail steps={SETUP_STEPS} current={step} railId={railId} stackWhenWide />
      <div className="relative min-w-0 overflow-hidden">
        <AnimatePresence mode="wait" initial={false} custom={offset}>
          <motion.div
            key={step}
            initial={{ opacity: 0, x: offset }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -offset }}
            transition={{ duration: reduceMotion ? 0 : 0.18, ease: "easeOut" }}
            className="flex flex-col gap-4"
          >
            {step === 0 ? (
              <div className="flex flex-col gap-2">
                <span id={methodLabelId} className="mb-2 text-sm font-medium">
                  How should codes reach you?
                </span>
                <RadioGroup
                  aria-labelledby={methodLabelId}
                  value={method}
                  onValueChange={(next) => {
                    const picked = METHODS.find((item) => item.id === next);
                    if (picked) setMethod(picked.id);
                  }}
                >
                  {METHODS.map(({ id, label, helper, Icon }) => (
                    <label
                      key={id}
                      className={cn(
                        "relative isolate flex cursor-pointer items-start gap-3 rounded-xl border p-3 has-focus-visible:ring-2 has-focus-visible:ring-ring",
                        method === id ? "border-foreground" : "border-border",
                      )}
                    >
                      <Icon aria-hidden="true" className="mt-0.5 size-4 shrink-0" />
                      <span className="flex flex-1 flex-col">
                        <span className="text-sm font-medium">{label}</span>
                        <span className="text-xs text-muted-foreground">{helper}</span>
                      </span>
                      <RadioGroupItem value={id} size="target" />
                    </label>
                  ))}
                </RadioGroup>
              </div>
            ) : null}

            {step === 1 ? (
              <div className="flex flex-col gap-4 @lg:flex-row">
                {method === "app" ? <SetupCode label="Setup code for your authenticator app" /> : null}
                <div className="flex min-w-0 flex-col gap-3">
                  <p className="text-sm">
                    {method === "app" ? (
                      <>
                        Scan the code with your app, or type this key: <span className="font-mono text-sm break-all">{SETUP_KEY}</span>
                      </>
                    ) : (
                      `We sent a 6-digit code to ${PHONE}.`
                    )}
                  </p>
                  <label htmlFor={codeId} className="text-sm font-medium">
                    6-digit code
                  </label>
                  <div className="flex gap-2">
                    <Input
                      id={codeId}
                      inputMode="numeric"
                      autoComplete="one-time-code"
                      maxLength={6}
                      value={code}
                      aria-invalid={error ? true : undefined}
                      aria-describedby={error ? `${codeId}-error` : undefined}
                      onChange={(event) => setCode(event.target.value.replace(/\D/g, ""))}
                      onKeyDown={(event) => (event.key === "Enter" && !event.nativeEvent.isComposing && event.keyCode !== 229 ? verify() : undefined)}
                      className="w-32"
                    />
                    <Button onClick={verify} disabled={checking}>
                      {checking ? <LoaderIcon aria-hidden="true" className="size-4 motion-safe:animate-spin" /> : null}
                      Confirm
                    </Button>
                  </div>
                  <p id={`${codeId}-error`} role="alert" className={cn("min-h-4 text-xs", STATUS_TEXT.bad)}>
                    {error}
                  </p>
                </div>
              </div>
            ) : null}

            {step === 2 ? (
              <div className="flex flex-col gap-3">
                <p className="text-sm">Each code works once. Keep them somewhere other than your phone.</p>
                <ul className="grid grid-cols-2 gap-2 rounded-xl bg-muted p-3 font-mono text-sm @lg:grid-cols-4">
                  {BACKUP_CODES.map((item) => (
                    <li key={item}>{item}</li>
                  ))}
                </ul>
                <p role="status" className="sr-only">
                  {copied ? "Backup codes copied." : ""}
                </p>
              </div>
            ) : null}
          </motion.div>
        </AnimatePresence>

        <div className="mt-4 flex flex-wrap justify-between gap-2">
          <Button variant="ghost" onClick={step === 0 ? onCancel : () => go(step - 1)}>
            {step === 0 ? "Cancel" : "Back"}
          </Button>
          <div className="flex gap-2">
            {step === 2 ? (
              <Button variant="outline" onClick={copy}>
                {copied ? "Copied" : "Copy codes"}
              </Button>
            ) : null}
            {step === 0 ? <Button onClick={() => go(1)}>Continue</Button> : null}
            {step === 2 ? <Button onClick={() => onDone(method)}>Turn on</Button> : null}
          </div>
        </div>
      </div>
    </div>
  );
}

const SIZE = 19;

/** A fixed pseudo-random fill for each cell, so the drawing is the same on every render. */
function filled(x: number, y: number) {
  const inFinder = (cx: number, cy: number) => x >= cx && x < cx + 5 && y >= cy && y < cy + 5;
  if (inFinder(0, 0) || inFinder(SIZE - 5, 0) || inFinder(0, SIZE - 5)) return false;
  const seed = Math.sin(x * 12.9898 + y * 78.233) * 43_758.5453;
  return seed - Math.floor(seed) > 0.52;
}

function finder(x: number, y: number) {
  return (
    <g key={`finder-${x}-${y}`}>
      <rect x={x + 0.5} y={y + 0.5} width={4} height={4} rx={1} fill="none" stroke="currentColor" />
      <rect x={x + 1.5} y={y + 1.5} width={2} height={2} rx={0.5} fill="currentColor" />
    </g>
  );
}

/**
 * Our own drawing of a setup code for an authenticator app. It stands in for
 * a real scannable code; the typed key under it carries the same secret.
 */
export function SetupCode({ label }: { label: string }) {
  const cells: { x: number; y: number }[] = [];
  for (let y = 0; y < SIZE; y += 1) for (let x = 0; x < SIZE; x += 1) if (filled(x, y)) cells.push({ x, y });
  return (
    <svg role="img" aria-label={label} viewBox={`-1 -1 ${SIZE + 2} ${SIZE + 2}`} className="size-36 shrink-0 rounded-xl border border-border bg-background p-2 text-foreground">
      {finder(0, 0)}
      {finder(SIZE - 5, 0)}
      {finder(0, SIZE - 5)}
      {cells.map((cell) => (
        <rect key={`${cell.x}-${cell.y}`} x={cell.x + 0.1} y={cell.y + 0.1} width={0.8} height={0.8} rx={0.2} fill="currentColor" />
      ))}
    </svg>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { CheckIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

/** Props for the rail of setup steps. */
export interface StepRailProps {
  steps: readonly { id: string; label: string }[];
  current: number;
  /** Names the marker so two rails on a page never share one. */
  railId: string;
  /** Stacks the steps once the frame is wide. Off, they always run across. */
  stackWhenWide?: boolean;
}

/**
 * The steps of a guided setup, in order, with a marker that glides to the
 * current one. Done steps show a tick. Under reduced motion the marker jumps.
 */
export function StepRail({ steps, current, railId, stackWhenWide = false }: StepRailProps) {
  const reduceMotion = useReducedMotion();
  return (
    <ol className={cn("flex gap-1", stackWhenWide && "@xl:flex-col")} aria-label="Steps">
      {steps.map((step, index) => {
        const done = index < current;
        const here = index === current;
        return (
          <li
            key={step.id}
            aria-current={here ? "step" : undefined}
            className={cn("relative isolate flex flex-1 items-center gap-2 rounded-lg px-2.5 py-2 text-sm", stackWhenWide && "@xl:flex-none", here ? "font-medium" : "text-muted-foreground")}
          >
            {here ? (
              <motion.span
                layoutId={`${railId}-marker`}
                aria-hidden="true"
                className="absolute inset-0 -z-10 rounded-lg bg-muted"
                transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 460, damping: 40 }}
              />
            ) : null}
            <span
              aria-hidden="true"
              className={cn(
                "flex size-5 shrink-0 items-center justify-center rounded-full border text-xs tabular-nums",
                done ? "border-transparent bg-chart-2 text-primary-foreground" : here ? "border-foreground" : "border-border",
              )}
            >
              {done ? <CheckIcon className="size-3" /> : index + 1}
            </span>
            <span className="hidden truncate @md:inline">{step.label}</span>
            <span className="sr-only @md:hidden">{step.label}</span>
            {done ? <span className="sr-only">, done</span> : null}
          </li>
        );
      })}
    </ol>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";

/** Props for a region that opens and closes with a height spring. */
export interface ExpandRegionProps {
  open: boolean;
  children: ReactNode;
  id?: string;
  className?: string;
}

/**
 * Grows from no height to its content's height on a spring with no bounce,
 * and shrinks back on close. Under reduced motion it opens and closes at once.
 */
export function ExpandRegion({ open, children, id, className }: ExpandRegionProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AnimatePresence initial={false}>
      {open ? (
        <motion.div
          key="region"
          id={id}
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: "auto", opacity: 1 }}
          exit={{ height: 0, opacity: 0 }}
          transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 380, damping: 40, opacity: { duration: 0.15 } }}
          className="overflow-hidden"
        >
          <div className={className}>{children}</div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}
